<script setup lang="ts">import{computed,ref}from"vue";import{jobProgress}from"@/domain/providers/statistics";import type{SyncJobRecord}from"@/domain/providers/records";const props=defineProps<{jobs:SyncJobRecord[]}>();const state=ref("");const provider=ref("");const providers=computed(()=>[...new Set(props.jobs.map(x=>x.provider))].sort());const filtered=computed(()=>props.jobs.filter(x=>(!state.value||x.estado===state.value)&&(!provider.value||x.provider===provider.value)));const label=(v?:string)=>({pendente:"Pendente",em_execucao:"Em execução",concluido:"Concluído",parcial:"Parcial",falhou:"Falhou",cancelado:"Cancelado"}[v||""]||v||"Sem estado");</script><template><section class="panel sync-job-panel" aria-labelledby="sync-job-title"><div class="section-heading"><div><p class="eyebrow">Sincronizações</p><h2 id="sync-job-title">Tarefas</h2></div><div class="maintenance-inline-filters"><select v-model="provider" aria-label="Filtrar por provider"><option value="">Todos os providers</option><option v-for="item in providers" :key="item">{{item}}</option></select><select v-model="state" aria-label="Filtrar por estado"><option value="">Todos os estados</option><option value="pendente">Pendente</option><option value="em_execucao">Em execução</option><option value="concluido">Concluído</option><option value="parcial">Parcial</option><option value="falhou">Falhou</option><option value="cancelado">Cancelado</option></select></div></div><div class="table-wrap"><table><thead><tr><th>Provider</th><th>Tipo</th><th>Estado</th><th>Progresso</th><th>Sucessos</th><th>Falhas</th><th>Erro</th></tr></thead><tbody><tr v-for="job in filtered" :key="job.id"><td>{{job.provider}}</td><td>{{job.tipo||'—'}}</td><td>{{label(job.estado)}}</td><td><div class="job-progress"><span :style="{width:`${jobProgress(job)}%`}"/></div><small>{{job.processados||0}} / {{job.total||0}}</small></td><td>{{job.sucessos||0}}</td><td>{{job.falhas||0}}</td><td>{{job.erro||'—'}}</td></tr></tbody></table></div></section></template>
